import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"स्व-विकास और स्व-संवर्धन का नियम","description":"","frontmatter":{},"headers":[],"relativePath":"hi/07-自生自长进化法则.md","filePath":"hi/07-自生自长进化法则.md"}'),d={name:"hi/07-自生自长进化法则.md"};function i(h,t,l,n,u,s){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="स्व-विकास-और-स्व-संवर्धन-का-नियम" tabindex="-1">स्व-विकास और स्व-संवर्धन का नियम <a class="header-anchor" href="#स्व-विकास-और-स्व-संवर्धन-का-नियम" aria-label="Permalink to &quot;स्व-विकास और स्व-संवर्धन का नियम&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>07</td></tr><tr><td>मॉड्यूल</td><td>सामान्य सिद्धांत और मूल सेटिंग्स</td></tr><tr><td>कीवर्ड</td><td>स्व-विकास, स्वायत्त विकास, आंतरिक प्रेरणा, गति-सम्मान, क्षमता विकास</td></tr></tbody></table><h2 id="i-स्व-विकास-और-स्व-संवर्धन-की-मूल-परिभाषा" tabindex="-1">I. स्व-विकास और स्व-संवर्धन की मूल परिभाषा <a class="header-anchor" href="#i-स्व-विकास-और-स्व-संवर्धन-की-मूल-परिभाषा" aria-label="Permalink to &quot;I. स्व-विकास और स्व-संवर्धन की मूल परिभाषा&quot;">​</a></h2><p>स्व-विकास और स्व-संवर्धन लंगर सहजीवी सभ्यता के केंद्रीय विकास नियमों में से एक है: हर जीवन का विकास अपनी आंतरिक स्वायत्त इच्छा और प्राकृतिक गति को मूल प्रेरक शक्ति बनाए, और बाहरी वातावरण तथा संस्थाएँ इस स्वायत्त विकास को समर्थन और गारंटी प्रदान करें, न कि जबरन हस्तक्षेप करें या अत्यधिक बढ़ावा दें। &quot;स्व-विकास&quot; इस बात पर ज़ोर देता है कि विकास की प्रेरक शक्ति जीवन से ही आती है; &quot;स्व-संवर्धन&quot; इस बात पर ज़ोर देता है कि विकास की गति जीवन के अपने नियमों का पालन करती है।</p><p>यह नियम शिकारवाद के &quot;जबरन विकास&quot; से स्पष्ट रूप से भिन्न है। शिकारवाद प्रायः दूसरों के मूल स्रोत को निगलकर, जबरन ऊर्जा-संचार, आत्मा-नियंत्रण आदि माध्यमों से तीव्र किंतु विकृत विकास प्राप्त करता है। हालाँकि यह विकास अल्पावधि में स्तर बढ़ा सकता है, दीर्घावधि में यह जीवन की स्वयं की विकास नींव को नष्ट कर देता है, जिससे मूल स्रोत अशुद्ध, स्तर अस्थिर और मन क्षतिग्रस्त हो जाता है। नियम का आग्रह है कि सच्चा ठोस विकास जीवन के भीतर से, अंदर से बाहर की ओर उगना चाहिए।</p><h2 id="ii-स्व-विकास-और-स्व-संवर्धन-के-सैद्धांतिक-आधार" tabindex="-1">II. स्व-विकास और स्व-संवर्धन के सैद्धांतिक आधार <a class="header-anchor" href="#ii-स्व-विकास-और-स्व-संवर्धन-के-सैद्धांतिक-आधार" aria-label="Permalink to &quot;II. स्व-विकास और स्व-संवर्धन के सैद्धांतिक आधार&quot;">​</a></h2><p>इस नियम की स्थापना जीवन विकास के नियमों की गहरी समझ पर आधारित है:</p><h3 id="_2-1-जीवन-की-स्वायत्तता-विकास-की-मूल-प्रेरक-शक्ति-है" tabindex="-1">2.1 जीवन की स्वायत्तता विकास की मूल प्रेरक शक्ति है <a class="header-anchor" href="#_2-1-जीवन-की-स्वायत्तता-विकास-की-मूल-प्रेरक-शक्ति-है" aria-label="Permalink to &quot;2.1 जीवन की स्वायत्तता विकास की मूल प्रेरक शक्ति है&quot;">​</a></h3><p>हर जीवन में आंतरिक विकास इच्छा और क्षमता होती है, और यह स्वायत्तता विकास की सबसे मौलिक और स्थायी प्रेरक शक्ति है। बाहरी प्रोत्साहन और समर्थन इस स्वायत्तता को प्रज्वलित कर सकते हैं, पर उसे प्रतिस्थापित नहीं कर सकते। जब कोई जीवन अपनी इच्छा और चयन से साधना करता है, तो उसकी साधना की एकाग्रता, रचनात्मकता और धैर्य जबरन या प्रलोभित साधना से कहीं अधिक होते हैं।</p><h3 id="_2-2-हर-जीवन-की-विकास-गति-अद्वितीय-होती-है" tabindex="-1">2.2 हर जीवन की विकास गति अद्वितीय होती है <a class="header-anchor" href="#_2-2-हर-जीवन-की-विकास-गति-अद्वितीय-होती-है" aria-label="Permalink to &quot;2.2 हर जीवन की विकास गति अद्वितीय होती है&quot;">​</a></h3><p>जातीय विशेषताओं, व्यक्तिगत दान, विकास वातावरण और मन की परिपक्वता में अंतर के कारण विभिन्न जीवनों की विकास गति भिन्न होती है। कुछ के लिए तीव्र सफलता उपयुक्त है, कुछ को धीमा संचय चाहिए; कुछ युवावस्था में ही उच्च स्तर पा सकते हैं, कुछ विलंब से खिलते हैं। नियम इस अंतर का सम्मान करता है और सभी जीवनों से एक समान समय-सारणी पर विकास की माँग नहीं करता।</p><h3 id="_2-3-जबरन-हस्तक्षेप-विकास-की-प्राकृतिक-नींव-को-नष्ट-करता-है" tabindex="-1">2.3 जबरन हस्तक्षेप विकास की प्राकृतिक नींव को नष्ट करता है <a class="header-anchor" href="#_2-3-जबरन-हस्तक्षेप-विकास-की-प्राकृतिक-नींव-को-नष्ट-करता-है" aria-label="Permalink to &quot;2.3 जबरन हस्तक्षेप विकास की प्राकृतिक नींव को नष्ट करता है&quot;">​</a></h3><p>साधना के इतिहास में अनेक मामले बताते हैं कि जबरन ऊर्जा-संचार, मूल-प्रत्यारोपण, आत्मा-नियंत्रण आदि से प्राप्त &quot;तीव्र विकास&quot; प्रायः गंभीर दुष्परिणामों के साथ आता है: स्तर अस्थिर, मूल अशुद्ध, आंतरिक दानव बढ़ते, आयु घटती, और यहाँ तक कि साधना-विचलन। इसका कारण यह है कि बाहर से थोपी गई शक्ति जीवन के स्वयं के मूल स्रोत से पूर्ण रूप से नहीं जुड़ पाती, जिससे &quot;पराया-अंग अस्वीकृति&quot; प्रभाव उत्पन्न होता है। हालाँकि स्व-विकसित विकास धीमा हो सकता है, हर कदम दृढ़ और गहरी नींव वाला होता है।</p><h2 id="iii-स्व-विकास-और-स्व-संवर्धन-के-व्यावहारिक-सिद्धांत" tabindex="-1">III. स्व-विकास और स्व-संवर्धन के व्यावहारिक सिद्धांत <a class="header-anchor" href="#iii-स्व-विकास-और-स्व-संवर्धन-के-व्यावहारिक-सिद्धांत" aria-label="Permalink to &quot;III. स्व-विकास और स्व-संवर्धन के व्यावहारिक सिद्धांत&quot;">​</a></h2><table tabindex="0"><thead><tr><th>सिद्धांत</th><th>अर्थ</th><th>व्यावहारिक आवश्यकताएँ</th></tr></thead><tbody><tr><td>स्वायत्त चयन सिद्धांत</td><td>साधक को साधना प्रणाली, विकास पथ और साधना गति चुनने का अधिकार</td><td>साधकों को विशिष्ट प्रणाली चुनने हेतु बाध्य न करें; एक समान सफलता-समय सारणी न बनाएँ</td></tr><tr><td>आंतरिक प्रेरणा सिद्धांत</td><td>साधना की प्रेरणा साधक की स्वयं की इच्छा और रुचि से आए</td><td>शिक्षा-मार्गदर्शन आंतरिक रुचि जगाने पर केंद्रित, दंड या लालच पर नहीं</td></tr><tr><td>गति-सम्मान सिद्धांत</td><td>हर साधक की अद्वितीय विकास गति का सम्मान</td><td>धीमी प्रगति पर भेदभाव या परित्याग न करें; व्यक्तिगत समर्थन योजनाएँ दें</td></tr><tr><td>नींव-प्राथमिकता सिद्धांत</td><td>विकास की दृढ़ता गति से अधिक महत्वपूर्ण</td><td>ठोस नींव बनाने को प्रोत्साहित करें; तीव्र सफलता हेतु नींव त्यागने को प्रोत्साहित न करें</td></tr><tr><td>त्रुटि-सहिष्णुता सिद्धांत</td><td>साधकों को विकास में गलतियाँ और चक्कर लगाने की अनुमति</td><td>त्रुटि-सहिष्णु तंत्र स्थापित करें; सुधार और समायोजन के अवसर दें</td></tr><tr><td>आत्म-साक्षात्कार सिद्धांत</td><td>विकास का अंतिम लक्ष्य जीवन का आत्म-साक्षात्कार, बाहरी मानदंड नहीं</td><td>स्तर की ऊँचाई को विकास सफलता का एकमात्र मानदंड न बनाएँ</td></tr></tbody></table><h2 id="iv-स्व-विकास-और-बाहरी-समर्थन-का-संबंध" tabindex="-1">IV. स्व-विकास और बाहरी समर्थन का संबंध <a class="header-anchor" href="#iv-स्व-विकास-और-बाहरी-समर्थन-का-संबंध" aria-label="Permalink to &quot;IV. स्व-विकास और बाहरी समर्थन का संबंध&quot;">​</a></h2><p>स्व-विकास और स्व-संवर्धन का अर्थ &quot;स्व-निर्वाह या उपेक्षा&quot; नहीं है। इसके विपरीत, स्व-विकास को पूर्ण रूप से साकार होने के लिए अच्छे बाहरी वातावरण और संस्थागत समर्थन की आवश्यकता है। सहजीवी सभ्यता स्व-विकास के लिए निम्नलिखित समर्थन प्रणालियाँ प्रदान करती है:</p><h3 id="_4-1-सूचना-समर्थन" tabindex="-1">4.1 सूचना समर्थन <a class="header-anchor" href="#_4-1-सूचना-समर्थन" aria-label="Permalink to &quot;4.1 सूचना समर्थन&quot;">​</a></h3><p>तीन सौ मूल साधना प्रणालियों का पूर्ण खुलापन हर साधक को पर्याप्त चयन स्थान देता है। साधक अपनी विशेषताओं के अनुसार समृद्ध प्रणाली-पुस्तकालय में सबसे उपयुक्त पथ पा सकता है। सभ्यता ने &quot;प्रणाली-संगतता मूल्यांकन तंत्र&quot; भी स्थापित किया है, जो लंगर जाल के माध्यम से साधकों को व्यक्तिगत प्रणाली-चयन सुझाव देता है, पर अंतिम चयन का अधिकार हमेशा साधक के पास रहता है।</p><h3 id="_4-2-संसाधन-समर्थन" tabindex="-1">4.2 संसाधन समर्थन <a class="header-anchor" href="#_4-2-संसाधन-समर्थन" aria-label="Permalink to &quot;4.2 संसाधन समर्थन&quot;">​</a></h3><p>उत्पादन-आधारित अनुबंध प्रणाली और मूल गारंटी प्रणाली यह सुनिश्चित करती हैं कि हर साधक को मूल साधना संसाधन मिलें। विशेष आवश्यकताओं वाले साधकों (जैसे जातीय विशेषताओं से उत्पन्न विशेष संसाधन आवश्यकताएँ) के लिए, सभ्यता लक्षित संसाधन आवंटन प्रदान करती है। संसाधन समर्थन का उद्देश्य साधकों की चिंताएँ दूर करना है, ताकि वे अपनी स्वयं की विकास गति पर ध्यान केंद्रित कर सकें।</p><h3 id="_4-3-गुरु-समर्थन" tabindex="-1">4.3 गुरु समर्थन <a class="header-anchor" href="#_4-3-गुरु-समर्थन" aria-label="Permalink to &quot;4.3 गुरु समर्थन&quot;">​</a></h3><p>अंतर-जातीय गुरु जाल साधकों को मार्गदर्शन और प्रश्न-उत्तर प्रदान करता है। गुरु की भूमिका &quot;पथ-प्रदर्शक&quot; है, &quot;नियंत्रक&quot; नहीं; गुरु अनुभव साझा कर सकते हैं, समस्याएँ बता सकते हैं, सुझाव दे सकते हैं, पर साधक को अपने ढंग से साधना हेतु बाध्य नहीं कर सकते। गुरु प्रणाली &quot;प्रश्नोत्तेजक शिक्षण&quot; पर ज़ोर देती है, जो साधक की स्वायत्त चिंतन क्षमता जगाती है।</p><h3 id="_4-4-वातावरण-समर्थन" tabindex="-1">4.4 वातावरण समर्थन <a class="header-anchor" href="#_4-4-वातावरण-समर्थन" aria-label="Permalink to &quot;4.4 वातावरण समर्थन&quot;">​</a></h3><p>सभ्यता ऐसा साधना वातावरण बनाने के लिए प्रतिबद्ध है जो अन्वेषण को प्रोत्साहित करे, अंतर सहन करे और चयन का सम्मान करे। साधक विभिन्न साधना विधियाँ स्वतंत्र रूप से आज़मा सकते हैं, बिना &quot;गैर-मुख्यधारा&quot; पथ चुनने पर भेदभाव के भय के। सभ्यता ने &quot;साधना नवाचार पुरस्कार तंत्र&quot; भी स्थापित किया है, जो साधकों को मौजूदा प्रणालियों पर नवाचार और व्यक्तिगत अनुकूलन के लिए प्रोत्साहित करता है।</p><h2 id="v-विशेष-परिस्थितियों-का-निपटान" tabindex="-1">V. विशेष परिस्थितियों का निपटान <a class="header-anchor" href="#v-विशेष-परिस्थितियों-का-निपटान" aria-label="Permalink to &quot;V. विशेष परिस्थितियों का निपटान&quot;">​</a></h2><p>स्व-विकास और स्व-संवर्धन का नियम सामान्यतः सार्वभौमिक रूप से लागू होता है, पर निम्नलिखित विशेष परिस्थितियों में विशेष निपटान आवश्यक है:</p><ul><li><strong>अवयस्क साधक</strong>: पूर्ण स्वायत्त निर्णय-क्षमता से रहित अवयस्क साधकों के लिए, उनके अभिभावक या जातीय शैक्षिक संस्थाएँ मार्गदर्शी साधना व्यवस्था प्रदान करती हैं, पर मन की परिपक्वता के साथ उनके स्वायत्त चयन अधिकार धीरे-धीरे बढ़ाए जाएँ</li><li><strong>मन-क्षतिग्रस्त</strong>: विभिन्न कारणों से मन क्षतिग्रस्त, अस्थायी रूप से स्वायत्त साधना में असमर्थ व्यक्तियों के लिए, सभ्यता उपचार और पुनर्वास समर्थन प्रदान करती है; स्वायत्त क्षमता बहाल होने के बाद वे स्व-विकास सिद्धांत का पालन करें</li><li><strong>विचलित</strong>: साधना में भटककर पागल हुए व्यक्तियों के लिए, सभ्यता जबरन हस्तक्षेप और बचाव प्रदान करती है, पर यह चिकित्सा-सहायता है, विकास-हस्तक्षेप नहीं; बचाव का उद्देश्य उनकी स्वायत्त विकास क्षमता बहाल करना है</li><li><strong>खतरनाक प्रवृत्ति</strong>: जिनकी साधना दिशा स्पष्ट रूप से शिकार-विरोध सिद्धांत का उल्लंघन करती है और स्वयं या दूसरों को गंभीर हानि पहुँचा सकती है, उन पर सभ्यता को प्रतिबंध और मार्गदर्शन का अधिकार है, पर यथासंभव शिक्षा और संवाद से, जबरन साधनों से नहीं</li></ul><h2 id="vi-स्व-विकास-का-सभ्यतागत-महत्व" tabindex="-1">VI. स्व-विकास का सभ्यतागत महत्व <a class="header-anchor" href="#vi-स्व-विकास-का-सभ्यतागत-महत्व" aria-label="Permalink to &quot;VI. स्व-विकास का सभ्यतागत महत्व&quot;">​</a></h2><p>इस नियम का सहजीवी सभ्यता के लिए गहरा महत्व है:</p><p>पहला, यह विकास की विविधता की रक्षा करता है। जब हर जीवन अपनी गति और पथ से विकसित होता है, तो ब्रह्मांड में रंगीन विकास रूप उभरते हैं; यह विविधता ब्रह्मांड के समग्र आयामी उन्नति का महत्वपूर्ण संसाधन है।</p><p>दूसरा, यह विकास की गुणवत्ता बढ़ाता है। स्व-विकसित विकास की नींव ठोस और मूल शुद्ध होता है; साधकों के स्तर अधिक स्थिर होते हैं, और उच्च स्तरों की सफलता की क्षमता अधिक होती है।</p><p>तीसरा, यह जीवन की गरिमा की रक्षा करता है। हर जीवन अपने विकास का स्वामी है, दूसरों द्वारा नियंत्रित उपकरण नहीं। यह स्वायत्तता जीवन की गरिमा का मूल प्रतीक है।</p><p>चौथा, यह विकास की रचनात्मकता जगाता है। जब साधक एक समान मानकों और गतियों से बंधे नहीं होते, तो वे बिल्कुल नए विकास पथ और विधियाँ खोजने की अधिक संभावना रखते हैं, तीन सौ प्रणालियों के निरंतर अनुकूलन में योगदान देते हैं।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>स्व-विकास और स्व-संवर्धन जीवन विकास के नियमों के प्रति लंगर सहजीवी सभ्यता का गहरा सम्मान है। यह हमें बताता है कि सच्चा विकास बाहरी शक्ति द्वारा थोपा गया परिणाम नहीं, बल्कि जीवन का स्वयं भीतर से बाहर की ओर उगना है। सभ्यता की सभी संस्थागत रचनाएँ अंततः हर जीवन के लिए ऐसा अच्छा वातावरण बनाने हेतु हैं जिसमें वह स्वयं विकसित हो सके, हर जीवन को अपनी गति से अपना सर्वश्रेष्ठ रूप बनने दे।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>08-人人有路保障体系 (हर किसी के लिए पथ गारंटी प्रणाली)</li><li>14-修炼境界统一划分 (साधना स्तरों का एकीकृत विभाजन)</li><li>37-共生教育体系 (सहजीवी शिक्षा प्रणाली)</li></ul>',38)])])}const c=a(d,[["render",i]]);export{p as __pageData,c as default};
